// A prism along z, centred: a regular polygon of sides sides (3 a triangle, 4 a square, ...), radius to its
// corners, a flat side down -- extruded. sides is live: dragging it needs no compile. shapes.js Nprism.
C = add_new(C, Nprism(p, sides, radius, height), MATERIAL);

// Round: every edge rounded by "radius" -- the shape grown outward by it, so it is that
// much bigger too. Free per step, but through a Hit of the children's own: inside, the
// medium is the nearest surface's rather than tracked per child (as in a CSG group).
var H = children(emptyHit(r), p);
H.s.w -= radius * XF_S;
C = fold(C, H.s, H.m);
